                requested_char = requested_char - 32;
            }

            if (*archive_cursor != requested_char) {
                break;
            }

            ++requested_cursor;
            ++archive_cursor;
        }

        if (*archive_cursor == 0 && *requested_cursor == 0) {
            goto found;
        }
    }

    ++entry_index;
    ++entry;
    if (entry_index < count) {
        goto scan_entry;
    }

not_found:
    return 0;

found:
